const text = [
  'Named Insured: Northwind Scaffolding LLC',
  'Policy Number: GL-88421-NW',
  'Insurance Company: Pinnacle Mutual Insurance',
  'Effective Date: 2026-01-19',
  'Expiry Date: 2026-10-24',
  'Coverages:',
  '- General Liability: $1,000,000 each occurrence / $2,000,000 aggregate'
].join('\n');
return [{ json: { filename: 'coi-northwind-scaffolding.pdf', text, schema: 'coi' } }];

const WINDOW_DAYS = 30;

function asObject(payload) {
  if (payload && payload.choices) {
    const content = payload.choices[0].message.content;
    return JSON.parse(content);
  }
  if (payload && payload.fields) return payload.fields;
  return payload;
}

function statusFor(dateStr) {
  if (!dateStr) return { status: 'unknown', days: null };
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);
  const due = new Date(String(dateStr).slice(0, 10) + 'T00:00:00Z');
  const days = Math.round((due - today) / 86400000);
  if (Number.isNaN(days)) return { status: 'unknown', days: null };
  if (days < 0) return { status: 'expired', days };
  if (days <= WINDOW_DAYS) return { status: 'expiring_soon', days };
  return { status: 'valid', days };
}

const input = $input.first().json;
const extracted = asObject(input);
const schema = extracted.vendor || extracted.invoice_number ? 'invoice' : 'coi';
const reasons = Array.isArray(extracted.review_reasons) ? extracted.review_reasons.slice() : [];
let needsReview = Boolean(extracted.needs_review);
const required = schema === 'invoice'
  ? ['vendor', 'invoice_number', 'total', 'due_date']
  : ['company_name', 'policy_number', 'insurer', 'expiry_date'];
for (const field of required) {
  const value = extracted[field];
  if (value === null || value === undefined || value === '') {
    needsReview = true;
    const label = 'Missing ' + field.replaceAll('_', ' ') + '.';
    if (!reasons.includes(label)) reasons.push(label);
  }
}
const relevant = schema === 'invoice' ? extracted.due_date : extracted.expiry_date;
const decided = statusFor(relevant);
const title = schema === 'invoice' ? extracted.vendor : extracted.company_name;
const reference = schema === 'invoice' ? extracted.invoice_number : extracted.policy_number;
return [{
  json: {
    id: schema + ':' + String(reference || title || 'row').replace(/\s+/g, '-'),
    schema,
    filename: input.filename || '',
    title: title || '',
    reference: reference || '',
    secondary: extracted.insurer || '',
    relevant_date: relevant || '',
    status: decided.status,
    days_until: decided.days,
    confidence: extracted.confidence ?? 0,
    needs_review: needsReview,
    review_reasons: reasons.join('; '),
    reminded_at: '',
    payload_json: JSON.stringify(extracted)
  }
}];

const WINDOW_DAYS = 30;
const today = new Date();
today.setUTCHours(0, 0, 0, 0);
const out = [];
for (const item of $input.all()) {
  const row = item.json;
  if (row.reminded_at) continue;
  const review = String(row.needs_review).toLowerCase();
  if (review === 'true' || review === 'yes' || row.needs_review === true) continue;
  const dateStr = row.relevant_date || row.expiry_date || row.due_date;
  if (!dateStr) continue;
  const due = new Date(String(dateStr).slice(0, 10) + 'T00:00:00Z');
  const days = Math.round((due - today) / 86400000);
  if (days >= 0 && days <= WINDOW_DAYS) {
    out.push({ json: { ...row, days_until: days } });
  }
}
return out;

const row = $input.first().json;
const days = Number(row.days_until);
const when = days === 0 ? 'today' : `in ${days} ${days === 1 ? 'day' : 'days'}`;
const isInvoice = row.schema === 'invoice';
const subject = isInvoice
  ? `Invoice due ${when}: ${row.reference} (${row.title})`
  : `Certificate expiring ${when}: ${row.title}`;
const body = [
  'Hello,',
  '',
  isInvoice
    ? 'An invoice in your tracker is coming due.'
    : 'A certificate of insurance in your tracker is approaching its expiry date.',
  '',
  `Name: ${row.title || ''}`,
  `Reference: ${row.reference || ''}`,
  `Date: ${row.relevant_date || ''}`,
  `Days remaining: ${days}`,
  '',
  'This reminder was selected by a fixed rule in the workflow, not by the model.',
  ''
].join('\n');
return [{ json: { ...row, subject, body, reminded_at: new Date().toISOString() } }];
